use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/group-profile216";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn timestamp(s:&str)->u128{let(a,b)=s.trim_end_matches(':').split_once('.').unwrap();assert_eq!(b.len(),9);a.parse::<u128>().unwrap()*1_000_000_000+b.parse::<u128>().unwrap()}
fn stream(phase:&str,name:&str)->String{let d=Path::new(ROOT).join(format!("{phase}-run/{name}"));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}fs::read_to_string(d.join("stdout.log")).unwrap()}
fn main(){let r=Path::new(ROOT);let old=read("/home/ubuntu/src/zopro-perf-work/group-pmu214/source/.xtask/source-pins.json");let(mut exact,mut changed)=(0,vec![]);for(p,h)in old.as_object().unwrap(){let rel=p.strip_prefix("/home/ubuntu/src/zopro-perf-work/group-pmu214/source/").unwrap();if hash(r.join("source").join(rel))==h.as_str().unwrap(){exact+=1;}else{changed.push(rel);}}assert_eq!(exact,181);assert_eq!(changed,["crates/zopro-core/src/boolean_phase_trace.rs"]);
let result=read(r.join("profile-result-symbolized.json"));assert_eq!(result["qualified"],true);let mut total=0;let mut pooled=BTreeMap::<bool,u64>::new();let mut bins=BTreeMap::<String,[u64;2]>::new();let mut pcs=BTreeMap::<u64,[u64;2]>::new();let mut rows=vec![];
for j in read(r.join("jobs.json")).as_array().unwrap().iter().filter(|j|j["sampled"]==true&&j["smoke"]==false){let name=j["name"].as_str().unwrap();let arm=j["boolean"]==true;let out=stream("main",name);let sync:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("CLOCKSYNC ")).unwrap()).unwrap();let mut lo=0u128;let mut hi=u128::MAX;for triple in sync["before"].as_array().unwrap().iter().chain(sync["after"].as_array().unwrap()){let a=triple[0].as_u64().unwrap()as u128;let b=triple[1].as_u64().unwrap()as u128;let c=triple[2].as_u64().unwrap()as u128;lo=lo.max(b-c);hi=hi.min(b-a);}assert!(lo<=hi&&hi-lo<=5000);let summary:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();let workers=summary["placement_before"]["worker_rows"].as_array().unwrap();let mut spans=vec![];for v in out.lines().filter_map(|l|l.strip_prefix("PHASE ")).map(|s|serde_json::from_str::<Value>(s).unwrap()){let worker=v["group_cpu"][2].as_u64().unwrap()-1;let tid=workers.iter().find(|w|w["index"]==worker).unwrap()["tid"].as_u64().unwrap();let a=v["events"][10].as_u64().unwrap()as u128;let b=v["events"][11].as_u64().unwrap()as u128;spans.push((tid,a,b));}assert_eq!(spans.len(),251);
let original=stream("verify",&format!("decode-{name}"));let resolved=stream("symbols",&format!("decode-{name}"));let a=original.lines().filter(|l|!l.trim().is_empty()).collect::<Vec<_>>();let b=resolved.lines().filter(|l|!l.trim().is_empty()).collect::<Vec<_>>();assert_eq!(a.len(),b.len());let retained=read(r.join(format!("{name}.symbolized-scoped-samples.json")));let retained=retained.as_array().unwrap();let(mut count,mut unknown,mut boundary)=(0,0,0);let mut oldunknown=0;for (line,new)in a.iter().zip(&b){let x=line.split_whitespace().collect::<Vec<_>>();let y=new.split_whitespace().collect::<Vec<_>>();assert_eq!(&x[..5],&y[..5]);assert_eq!(x[3],"1000000");let pidtid=x[0].split_once('/').unwrap();assert_eq!(pidtid.0.parse::<u64>().unwrap(),sync["pid"].as_u64().unwrap());let tid=pidtid.1.parse::<u64>().unwrap();let time=timestamp(x[2]);let possible=spans.iter().filter(|&&(t,s,e)|t==tid&&time>=s+lo&&time<e+hi).count();let definite=spans.iter().filter(|&&(t,s,e)|t==tid&&time>=s+hi&&time<e+lo).count();assert!(possible<=1&&definite<=possible);if definite==0{boundary+=possible;continue;}let row=&retained[count];assert_eq!(row["tid"],tid);assert_eq!(row["time_ns"].as_u64().unwrap()as u128,time);assert_eq!(row["ip"],x[4].trim_start_matches('0'));let symbol=row["symbol"].as_str().unwrap();unknown+=usize::from(y[5]=="[unknown]");oldunknown+=usize::from(x[5]=="[unknown]");*pooled.entry(arm).or_default()+=1;let offset=row["offset"].as_u64().unwrap();let bin=format!("{symbol}+0x{:x}",offset/64*64);bins.entry(bin).or_default()[arm as usize]+=1;if symbol=="zopro_core::msm_affine::grouping::scalar_groups"{pcs.entry(offset).or_default()[arm as usize]+=1;}count+=1;}
assert_eq!(count,retained.len());let reported=result["rows"].as_array().unwrap().iter().find(|v|v["name"]==name).unwrap();assert_eq!(reported["G2_scoped"],count);assert_eq!(reported["boundary_ambiguous"],boundary);assert_eq!(reported["samples"],b.len());assert!(unknown as f64/count as f64<=0.05);total+=b.len();rows.push(json!({"name":name,"samples_unchanged":b.len(),"scoped":count,"boundary":boundary,"old_unknown":oldunknown,"resolved_unknown":unknown,"sync_width_ns":hi-lo}));}
assert_eq!(pooled[&false],1265);assert_eq!(pooled[&true],692);let mut bins=bins.into_iter().map(|(s,c)|json!({"bin":s,"OFF":c[0],"ON":c[1],"OFF_minus_ON":c[0]as i64-c[1]as i64})).collect::<Vec<_>>();bins.sort_by_key(|v|std::cmp::Reverse(v["OFF_minus_ON"].as_i64().unwrap()));let mut pcs=pcs.into_iter().map(|(o,c)|json!({"offset":o,"vaddr":format!("{:x}",0x233bb0+o),"OFF":c[0],"ON":c[1]})).collect::<Vec<_>>();pcs.sort_by_key(|v|std::cmp::Reverse(v["OFF"].as_u64().unwrap()));let v=json!({"pass":true,"source214_exact":exact,"source214_changed":changed,"rows":rows,"samples_unchanged":total,"pooled_OFF":1265,"pooled_ON":692,"bins":bins,"pcs":pcs,"no_new_capture":true,"no_quality_gate_change":true});let p=r.join("independent-profile-review.json");assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Independent scope/source/sample-invariance PASS; {total} samples unchanged; OFF1265/ON692");}
